SELECT json_build_object('plans',(SELECT json_agg(t) FROM (SELECT execution_id,plan_hash,status FROM execution_plans WHERE execution_id IN ('d9e6a5ba-283c-47a3-918b-479d3ce8afaf'::uuid,'ba0e8c8c-1085-490f-893f-edfd62d61460'::uuid,'9f86cba0-8540-4323-94a3-9cb749fef64c'::uuid,'667988a2-f2a1-4637-8d96-175998f9e9cf'::uuid,'33925f23-aef1-4d3b-88be-4c74a835415a'::uuid))t),'calls',(SELECT json_agg(t) FROM (SELECT l.execution_id,l.trace_id,l.purpose,l.provider,l.model_id,l.input_tokens,l.output_tokens,l.created_at,s.generation_params_json,s.input_refs_json FROM llm_usage_ledger l JOIN prompt_snapshots s ON s.id=l.prompt_snapshot_id WHERE l.execution_id IN ('d9e6a5ba-283c-47a3-918b-479d3ce8afaf'::uuid,'ba0e8c8c-1085-490f-893f-edfd62d61460'::uuid,'9f86cba0-8540-4323-94a3-9cb749fef64c'::uuid,'667988a2-f2a1-4637-8d96-175998f9e9cf'::uuid,'33925f23-aef1-4d3b-88be-4c74a835415a'::uuid) ORDER BY l.created_at)t));